{"arguments": {"content": "#!/usr/bin/env python3
import sys
import openpyxl

def is_yellow(cell):
    """Return True if the cell has a solid yellow fill (FFFFF00/FFFFFE00)."""
    fill = cell.fill
    if fill is None or fill.patternType != 'solid':
        return False
    fg = fill.fgColor
    if fg is None:
        return False
    rgb = str(fg.rgb)
    return rgb.upper() in ('FFFFFF00', 'FFFFF00', 'FFFFFF00FF')

def apply_prefix_formula(coordinate):
    """Add '//' prefix before the '[' in a CONCATENATE formula string."""
    if not isinstance(coordinate, str):
        return coordinate
    if not coordinate.startswith('=CONCATENATE("['):
        return coordinate
    return coordinate.replace('=CONCATENATE("[', '=CONCATENATE("//[', 1)

def main():
    spreadsheet_path = sys.argv[1]
    output_path = sys.argv[2]

    wb = openpyxl.load_workbook(spreadsheet_path)
    ws = wb.active

    for row in ws.iter_rows():
        for cell in row:
            if cell.column_letter != 'G':
                continue
            if is_yellow(cell):
                cell.value = apply_prefix_formula(cell.value)

    wb.save(output_path)

if __name__ == '__main__':
